-- Enable extension
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- Add GIN index for fast fuzzy search
CREATE INDEX idx_items_title_trgm ON items USING GIN (title gin_trgm_ops);

-- Search with fuzzy matching (finds "bycicle" when searching "bicycle")
SELECT title, similarity(title, 'bycicle') AS score
FROM items
WHERE title % 'bycicle'  -- % is similarity operator
ORDER BY score DESC;

-- Full-text search (already exists)
CREATE INDEX idx_items_title_description_fts ON items USING GIN (
  to_tsvector('english', title || ' ' || COALESCE(description, ''))
);

-- NEW indexes for filters
CREATE INDEX idx_items_age_group ON items(age_group) WHERE status = 'available';
CREATE INDEX idx_items_gender ON items(gender) WHERE status = 'available';
CREATE INDEX idx_items_brand ON items(brand) WHERE status = 'available';
CREATE INDEX idx_items_color ON items USING GIN(color) WHERE status = 'available'; -- GIN for array
CREATE INDEX idx_items_price ON items(price) WHERE status = 'available';

-- Composite index for common filter combos (optional, may add later)
CREATE INDEX idx_items_category_price ON items(category_id, price) WHERE status = 'available';

